select public.admin_notify('🔧 Token/Secret kahan milenge — exact paths', 'Roles me dono accounts Instagram Tester add ho gaye ✔ (proof screenshot). Tokens abhi isliye nahi mile kyunki SUAT flow me pehle **Login URL** se grant lena hota hai: Login URL copy → har IG account se alag browser/incognito me kholo → Allow → (miniesports.local error page = normal) → phir section 2 me account dikhega → Generate token → copy (ek baar dikhta hai). App Secret: left menu → Settings → Basic → "App secret" → Show → OTP/password → copy. Note: 1149100804208223 = Configuration ID tha; asli App ID bhi Settings→Basic me hai. Sab kuch private Drive file me hi.', 'session_end') as notified;
